SELECT DISTINCT md.chembl_id AS molecule_chembl_id, md.pref_name AS molecule_name, md.max_phase, md.molecule_type, cs.canonical_smiles FROM molecule_dictionary md JOIN compound_records r ON md.molregno = r.molregno JOIN docs d ON r.doc_id = d.doc_id JOIN compound_structures cs ON md.molregno = cs.molregno WHERE d.chembl_id = 'CHEMBL1136837' ORDER BY md.chembl_id
